int main(void)
{
    HMODULE module = GetModuleHandleW(NULL);
    trace_file = fopen("boot_trace.log", "a");
    if (!AddVectoredExceptionHandler(1, trace_vectored_exception)) {
        trace_log("event=setup_failure operation=AddVectoredExceptionHandler win32_error=%lu\n", GetLastError());
        return 13;
    }
    black_xbox_thread_finished = CreateEventW(NULL, TRUE, FALSE, NULL);
    if (!black_xbox_thread_finished) {
        trace_log("event=setup_failure operation=CreateEvent win32_error=%lu\n", GetLastError());
        return 12;
    }
    guest_image = (uint8_t *)VirtualAlloc(NULL, BLACK_GUEST_IMAGE_SIZE, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
    if (!guest_image) {
        trace_log("event=setup_failure operation=VirtualAlloc guest_base=0x%08X guest_size=0x%08X win32_error=%lu\n",
            BLACK_GUEST_IMAGE_BASE, BLACK_GUEST_IMAGE_SIZE, GetLastError());
        return 10;
    }
    trace_log("event=guest_image_address_space base=0x%08X size=0x%08X identity_mapping=%u\n",
        (uint32_t)(uintptr_t)guest_image, BLACK_GUEST_IMAGE_SIZE,
        (uint32_t)((uintptr_t)guest_image == BLACK_GUEST_IMAGE_BASE));
    if (!load_xbe_header()) { trace_log("event=setup_failure operation=load_xbe_header\n"); goto setup_failure; }
    if (!initialize_xbox_thread_context(&black_xbox_main_context)) { trace_log("event=setup_failure operation=initialize_main_thread_context\n"); goto setup_failure; }
    if (!initialize_xbox_thread_context(&black_xbox_system_context)) { trace_log("event=setup_failure operation=initialize_system_thread_context\n"); goto setup_failure; }
    black_xbox_active_context = &black_xbox_main_context;
    {
        uint32_t thread_id = GetCurrentThreadId();
        memcpy(black_xbox_main_context.thread_metadata + 0x12Cu, &thread_id, sizeof(thread_id));
    }
    if (!patch_guest_operands(module)) { trace_log("event=setup_failure operation=patch_guest_operands\n"); goto setup_failure; }
    if (!install_a2df8_trace()) { trace_log("event=setup_failure operation=install_a2df8_trace\n"); goto setup_failure; }
    if (!install_a39f1_trace()) { trace_log("event=setup_failure operation=install_a39f1_trace\n"); goto setup_failure; }
    if (!install_a39ec_trace()) { trace_log("event=setup_failure operation=install_a39ec_trace\n"); goto setup_failure; }
    if (!patch_xbox_tls_base_read()) { trace_log("event=setup_failure operation=patch_xbox_tls_base_read\n"); goto setup_failure; }
    if (!patch_xbox_thread_id_fs_read()) { trace_log("event=setup_failure operation=patch_xbox_thread_id_fs_read\n"); goto setup_failure; }
    if (!install_ceil_entry_trace()) { trace_log("event=setup_failure operation=install_ceil_entry_trace\n"); goto setup_failure; }
    if (!install_ceil_controlfp_block_trace()) { trace_log("event=setup_failure operation=install_ceil_controlfp_block_trace\n"); goto setup_failure; }
    if (!install_import_traps()) { trace_log("event=setup_failure operation=install_import_traps\n"); goto setup_failure; }

    BlackGuestFunction callback = black_resolve_guest_runtime_target(0x000259CB);
    BlackGuestFunction unknown = black_resolve_guest_runtime_target(0xDEADBEEF);
    trace_log("event=startup module_base=0x%08X guest_image=0x%08X guest_size=0x%08X entry_guest_va=0x00025A3F guest_data=header_rdata_data\n",
        (uint32_t)(uintptr_t)module, (uint32_t)(uintptr_t)guest_image, BLACK_GUEST_IMAGE_SIZE);
    trace_log("event=guest_function_map functions=%u callback_guest_va=0x000259CB callback_host=0x%08X unknown_resolves=%u map_self_check=%u\n",
        black_guest_function_count(), (uint32_t)(uintptr_t)callback, unknown != 0, black_guest_function_map_self_check());
    __try {
        xbe_entry_point();
    }
    __except (capture_exception(GetExceptionInformation())) {
        uint32_t stack[16] = { 0 };
        SIZE_T stack_bytes = 0;
        ReadProcessMemory(GetCurrentProcess(), (const void *)(uintptr_t)guest_exception_context.Esp,
            stack, sizeof(stack), &stack_bytes);
        trace_log("event=exception code=0x%08lX host_eip=0x%08lX access_type=%lu fault_address=0x%08lX last_import=%s last_import_call_rva=0x%08X\n",
            guest_exception_code, guest_exception_ip, guest_access_type, guest_fault_address,
            last_import_name ? last_import_name : "none", last_import_return_rva);
        trace_log("event=cpu_context eax=%08lX ebx=%08lX ecx=%08lX edx=%08lX esi=%08lX edi=%08lX ebp=%08lX esp=%08lX eflags=%08lX\n",
            guest_exception_context.Eax, guest_exception_context.Ebx, guest_exception_context.Ecx,
            guest_exception_context.Edx, guest_exception_context.Esi, guest_exception_context.Edi,
            guest_exception_context.Ebp, guest_exception_context.Esp, guest_exception_context.EFlags);
        trace_log("event=stack bytes_read=%lu words=", (unsigned long)stack_bytes);
        for (size_t i = 0; i < stack_bytes / sizeof(stack[0]); ++i) {
            trace_log("%s%08X", i ? "," : "", stack[i]);
        }
        trace_log("\n");
        VirtualFree(guest_image, 0, MEM_RELEASE);
        if (trace_file) fclose(trace_file);
        return 20;
    }

    trace_log("event=entry_returned\n");
    if (InterlockedCompareExchange(&black_xbox_thread_started, 0, 0)) {
        trace_log("event=waiting_for_guest_system_thread\n");
        WaitForSingleObject(black_xbox_thread_finished, INFINITE);
        trace_log("event=guest_system_thread_finished\n");
    }
    VirtualFree(guest_image, 0, MEM_RELEASE);
    CloseHandle(black_xbox_thread_finished);
    if (trace_file) fclose(trace_file);
    return 0;

setup_failure:
    VirtualFree(guest_image, 0, MEM_RELEASE);
    return 11;
}
